import java.util.*;

public class Main {
    int missingNumber(int[] nums) {
        int n = nums.length;
        for (int candidate = 0; candidate <= n; candidate++) {      // try every number in the expected range
            boolean found = false;
            for (int num : nums) {                                    // linear search through the whole array
                if (num == candidate) { found = true; break; }
            }
            if (!found) return candidate;
        }
        return -1;
    }

    public static void main(String[] args) {
        int[] nums = {3, 0, 1};
        Main solution = new Main();
        System.out.println(solution.missingNumber(nums));
    }
}

