public class Main {
    int missingNumber(int[] nums) {
        int n = nums.length;
        long expectedSum = (long) n * (n + 1) / 2;                  // sum of every number from 0 to n
        long actualSum = 0;
        for (int num : nums) actualSum += num;
        return (int) (expectedSum - actualSum);                      // whatever is left over is the missing number
    }

    public static void main(String[] args) {
        int[] nums = {3, 0, 1};
        Main solution = new Main();
        System.out.println(solution.missingNumber(nums));
    }
}

